53	import org.springframework.beans.factory.annotation.Value;
54	import org.springframework.stereotype.Service;
55	
56	/**
57	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
58	 * so tests can assert side-effects by reading that file — the second test-assertion channel
59	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
60	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
61	 *
62	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
63	 * SYNC) so a test reads the record immediately.
64	 */
65	@Service
66	public class Audit {
67	
68	    private final Path file;
69	
70	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
71	        this.file = Path.of(path);
72	    }
73	
74	    /** Append one audit record. Tests assert the exact line(s) in the file. */
75	    public synchronized void record(String entry) {
76	        try {
77	            Path parent = file.toAbsolutePath().getParent();
78	            if (parent != null) {
79	                Files.createDirectories(parent);
80	            }
81	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
82	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
83	        } catch (IOException e) {
84	            throw new UncheckedIOException(e);
85	        }
86	    }
87	
88	    /** Truncate the audit file. */
89	    public synchronized void clear() {
90	        try {
91	            Files.deleteIfExists(file);
92	        } catch (IOException e) {
93	            throw new UncheckedIOException(e);
94	        }
95	    }
96	}
