114	
115	    @Override
116	    public void addResourceHandlers(ResourceHandlerRegistry registry) {
117	        registry.addResourceHandler("/**")
118	                .addResourceLocations("classpath:/static/")
119	                .resourceChain(true)
120	                .addResolver(new PathResourceResolver() {
121	                    @Override
122	                    protected Resource getResource(String resourcePath, Resource location) throws IOException {
123	                        if (resourcePath.startsWith("api/")) {
124	                            return null; // let the API handle / 404 it
125	                        }
126	                        Resource requested = location.createRelative(resourcePath);
127	                        return (requested.exists() && requested.isReadable())
128	                                ? requested
129	                                : location.createRelative("index.html");
130	                    }
131	                });
132	    }
