322	import org.springframework.dao.DataIntegrityViolationException;
323	import org.springframework.stereotype.Service;
324	import org.springframework.transaction.annotation.Transactional;
325	
326	/** Keeps the people on a sheet. */
327	@Service
328	public class PersonService {
329	
330	    private final PersonRepository people;
331	    private final SheetRepository sheets;
332	
333	    public PersonService(PersonRepository people, SheetRepository sheets) {
334	        this.people = people;
335	        this.sheets = sheets;
336	    }
337	
338	    public List<Person> list(String sheetId) {
339	        return people.findBySheetIdOrderByIdAsc(sheetId);
340	    }
341	
342	    @Transactional
343	    public Person add(String sheetId, String name, String grade) {
344	        if (!sheets.existsById(sheetId)) {
345	            throw new SheetNotFoundException(sheetId);
346	        }
347	        if (people.existsBySheetIdAndNameKey(sheetId, Person.key(name))) {
348	            throw new PersonNameTakenException(sheetId, name.trim());
349	        }
350	        return save(new Person(sheetId, name, grade));
351	    }
352	
353	    @Transactional
354	    public Person update(String sheetId, Long id, String name, String grade) {
355	        Person person = people.findByIdAndSheetId(id, sheetId)
356	                .orElseThrow(() -> new PersonNotFoundException(sheetId, id));
357	        if (people.existsBySheetIdAndNameKeyAndIdNot(sheetId, Person.key(name), id)) {
358	            throw new PersonNameTakenException(sheetId, name.trim());
359	        }
360	        person.setName(name);
361	        person.setGrade(grade);
362	        return save(person);
363	    }
364	
365	    private Person save(Person person) {
366	        try {
367	            return people.saveAndFlush(person);
368	        } catch (DataIntegrityViolationException e) {
369	            // Another user took the name at the same moment: the unique index refused it.
370	            throw new PersonNameTakenException(person.getSheetId(), person.getName());
371	        }
372	    }
373	}
