380	
381	/**
382	 * Loads a sheet by id, starting an empty one the first time the id is used, and keeps the sheet's
383	 * today. The real clock is read only once, to give a new sheet its starting today; everything else
384	 * dated uses {@link #today(String)}.
385	 */
386	@Service
387	public class SheetService {
388	
389	    private final SheetRepository sheets;
390	
391	    public SheetService(SheetRepository sheets) {
392	        this.sheets = sheets;
393	    }
394	
395	    public Sheet load(String id, String user) {
396	        return sheets.findById(id).orElseGet(() -> start(id, user));
397	    }
398	
399	    /** The sheet's today: use it for every date-dependent decision and default date. */
400	    public LocalDate today(String id) {
401	        return sheets.findById(id).map(Sheet::getToday).orElseThrow(() -> new SheetNotFoundException(id));
402	    }
403	
404	    @Transactional
405	    public Sheet setToday(String id, LocalDate today) {
406	        Sheet sheet = sheets.findById(id).orElseThrow(() -> new SheetNotFoundException(id));
407	        sheet.setToday(today);
408	        return sheets.saveAndFlush(sheet);
409	    }
410	
411	    private Sheet start(String id, String user) {
412	        try {
413	            return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now()));
414	        } catch (DataIntegrityViolationException e) {
415	            // Another user started the same sheet at the same moment: it exists now.
416	            return sheets.findById(id).orElseThrow(() -> e);
417	        }
418	    }
419	}
