555	  protected readonly editing = signal<number | null>(null);
556	  protected readonly error = signal<string | null>(null);
557	  private reads = 0;
558	
559	  constructor() {
560	    effect(() => {
561	      const sheet = this.session.sheet();
562	      this.session.loaded();
563	      untracked(() => {
564	        this.people.set([]);
565	        this.reset();
566	        if (sheet) void this.read(sheet);
567	      });
568	    });
569	  }
