577	    this.name.set(person.name);
578	    this.grade.set(person.grade);
579	    this.error.set(null);
580	  }
581	
582	  protected reset(): void {
583	    this.editing.set(null);
584	    this.name.set('');
585	    this.grade.set('A');
586	    this.error.set(null);
587	  }
588	
589	  protected async submit(event: Event): Promise<void> {
590	    event.preventDefault();
591	    this.error.set(null);
592	    const sheet = this.session.sheet();
593	    if (!sheet) return;
594	    const body = { name: this.name(), grade: this.grade() };
595	    if (!body.name.trim()) {
596	      this.error.set('Type a name for the person.');
597	      return;
598	    }
599	    const editing = this.editing();
600	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people`;
601	    try {
602	      if (editing === null) {
603	        const added = await firstValueFrom(this.http.post<Person>(url, body, this.session.headers()));
