616	        void this.read(sheet);
617	      }
618	    } catch (e) {
619	      if (e instanceof HttpErrorResponse && e.status === 409) {
620	        this.error.set('Another person on the sheet already has that name.');
621	      } else {
622	        this.error.set(editing === null ? 'The person could not be added.' : 'The person could not be saved.');
