627	  private async read(sheet: string): Promise<void> {
628	    const read = ++this.reads;
629	    const list = await firstValueFrom(
630	      this.http.get<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`, this.session.headers()),
631	    ).catch(() => null);
632	    // A later read wins over a slower earlier one.
633	    if (list && read === this.reads && this.session.sheet() === sheet) this.people.set(list);
634	  }
635	}
