814	# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
815	# db/migration; Actuator health is the readiness probe.
816	
817	# In-memory H2 (dies with the JVM = clean per-run reset).
818	spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
819	spring.datasource.driver-class-name=org.h2.Driver
820	spring.datasource.username=sa
821	spring.datasource.password=
822	# Pooled connections are never retired: when HikariCP closes one at its default 30 min
823	# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
824	# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
825	spring.datasource.hikari.max-lifetime=0
826	
827	# Flyway owns the schema. JPA does not create tables.
828	spring.flyway.enabled=true
829	spring.jpa.hibernate.ddl-auto=none
830	# Close the persistence context at the end of the request, not during view rendering.
831	spring.jpa.open-in-view=false
832	
833	# Readiness probe.
834	management.endpoints.web.exposure.include=health
835	management.endpoint.health.probes.enabled=true
836	
837	# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
838	# fallback is in SpaConfig.java.
839	
840	# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
841	# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
842	app.audit.file=${AUDIT_FILE:.run/audit.log}
